--
-- Table structure for table `holidays`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `holidays` (
  `name` varchar(200) NOT NULL,
  `kind` varchar(48) NOT NULL,
  `year` smallint NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `days_count` smallint NOT NULL,
  `region_code` varchar(12) NOT NULL,
  `scope_key` varchar(200) NOT NULL,
  `definition_source_id` varchar(36) NOT NULL,
  `definition_asset_id` varchar(36) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `row_version` int NOT NULL,
  `id` varchar(36) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `holiday_scope` (`kind`,`year`,`region_code`,`scope_key`),
  KEY `fk_holidays_definition_asset_id_source_assets` (`definition_asset_id`),
  KEY `fk_holidays_definition_source_id_sources` (`definition_source_id`),
  CONSTRAINT `fk_holidays_definition_asset_id_source_assets` FOREIGN KEY (`definition_asset_id`) REFERENCES `source_assets` (`id`),
  CONSTRAINT `fk_holidays_definition_source_id_sources` FOREIGN KEY (`definition_source_id`) REFERENCES `sources` (`id`),
  CONSTRAINT `ck_holidays_date_order` CHECK ((`end_date` >= `start_date`)),
  CONSTRAINT `ck_holidays_days_positive` CHECK ((`days_count` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

