--
-- Table structure for table `ingestion_runs`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ingestion_runs` (
  `source_id` varchar(36) NOT NULL,
  `job_id` varchar(36) DEFAULT NULL,
  `attempt_id` varchar(36) DEFAULT NULL,
  `asset_id` varchar(36) DEFAULT NULL,
  `status` varchar(48) NOT NULL,
  `dry_run` tinyint(1) NOT NULL,
  `reason` text NOT NULL,
  `parser_version` varchar(64) NOT NULL,
  `normalizer_version` varchar(64) NOT NULL,
  `quality_rule_version` varchar(64) NOT NULL,
  `started_at` datetime(6) NOT NULL,
  `finished_at` datetime(6) DEFAULT NULL,
  `processed_count` int NOT NULL,
  `imported_count` int NOT NULL,
  `revised_count` int NOT NULL,
  `skipped_count` int NOT NULL,
  `quarantined_count` int NOT NULL,
  `error_summary` text,
  `id` varchar(36) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_ingestion_runs_asset_id_source_assets` (`asset_id`),
  KEY `fk_ingestion_runs_attempt_id_job_attempts` (`attempt_id`),
  KEY `fk_ingestion_runs_job_id_jobs` (`job_id`),
  KEY `ix_ingestion_runs_source_started` (`source_id`,`started_at`),
  CONSTRAINT `fk_ingestion_runs_asset_id_source_assets` FOREIGN KEY (`asset_id`) REFERENCES `source_assets` (`id`),
  CONSTRAINT `fk_ingestion_runs_attempt_id_job_attempts` FOREIGN KEY (`attempt_id`) REFERENCES `job_attempts` (`id`),
  CONSTRAINT `fk_ingestion_runs_job_id_jobs` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`),
  CONSTRAINT `fk_ingestion_runs_source_id_sources` FOREIGN KEY (`source_id`) REFERENCES `sources` (`id`),
  CONSTRAINT `ck_ingestion_runs_imported_count_nonnegative` CHECK ((`imported_count` >= 0)),
  CONSTRAINT `ck_ingestion_runs_processed_count_nonnegative` CHECK ((`processed_count` >= 0)),
  CONSTRAINT `ck_ingestion_runs_quarantined_count_nonnegative` CHECK ((`quarantined_count` >= 0)),
  CONSTRAINT `ck_ingestion_runs_revised_count_nonnegative` CHECK ((`revised_count` >= 0)),
  CONSTRAINT `ck_ingestion_runs_skipped_count_nonnegative` CHECK ((`skipped_count` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

