  CONSTRAINT `fk_knowledge_indexes_job_id_jobs` FOREIGN KEY (`job_id`) REFERENCES `jobs` (`id`),
  CONSTRAINT `ck_knowledge_indexes_chunk_count_nonnegative` CHECK ((`chunk_count` >= 0))
