CREATE TABLE `public_data_facts` (
  `id` varchar(64) NOT NULL,
  `origin` varchar(32) NOT NULL,
  `origin_key` varchar(128) NOT NULL,
  `entity_key` varchar(100) NOT NULL,
  `entity_name` varchar(255) NOT NULL,
  `entity_type` varchar(40) NOT NULL,
  `metric_code` varchar(100) NOT NULL,
  `scope` varchar(200) NOT NULL,
  `grain` varchar(32) NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `value` decimal(24,4) NOT NULL,
  `unit` varchar(40) NOT NULL,
  `quality_status` varchar(40) NOT NULL,
  `qualifier` text,
  `source_url` text NOT NULL,
  `source_title` text NOT NULL,
  `published_at` datetime(6) DEFAULT NULL,
  `provenance` json NOT NULL,
  `raw_record` json NOT NULL,
  `previous_versions` json NOT NULL,
  `content_sha256` varchar(64) NOT NULL,
  `observation_id` varchar(36) DEFAULT NULL,
  `import_id` varchar(36) NOT NULL,
  `imported_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_public_data_facts_observation_id_observations` (`observation_id`),
  KEY `fk_public_data_facts_import_id_public_data_imports` (`import_id`),
  KEY `ix_public_data_entity_period` (`entity_name`,`period_start`),
  KEY `ix_public_data_quality_metric` (`quality_status`,`metric_code`),
  CONSTRAINT `fk_public_data_facts_import_id_public_data_imports` FOREIGN KEY (`import_id`) REFERENCES `public_data_imports` (`id`),
  CONSTRAINT `fk_public_data_facts_observation_id_observations` FOREIGN KEY (`observation_id`) REFERENCES `observations` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
